import pytest

if pytest.use_correct:
    from correct_python_programs.lis import lis
else:
    from python_programs.lis import lis


def test_attack_1():
    # docstring example: longest must survive a later small tail update
    assert lis([4, 1, 5, 3, 7, 6, 2]) == 3


def test_attack_2():
    # minimal shrink bug: longest must not decrease after trailing small element
    assert lis([2, 3, 1]) == 2


def test_attack_3():
    # shrink followed by partial recovery must still report old longest
    assert lis([3, 4, 5, 1, 2]) == 3


def test_attack_4():
    # tail replacement is required: without it the later 3,4 cannot extend
    assert lis([1, 5, 2, 3, 4]) == 4


def test_attack_5():
    # strictly decreasing: must stay 1, kills unconditional increment mutants
    assert lis([5, 4, 3, 2, 1]) == 1


def test_attack_6():
    # edge cases: empty, single, strictly increasing
    assert lis([]) == 0
    assert lis([7]) == 1
    assert lis([1, 2, 3, 4, 5]) == 5


def test_attack_7():
    # long prefix then short suffix: true LIS is the early run
    assert lis([10, 20, 30, 1, 2]) == 3
